function v53ExactBirthTime(s){assert.equal(typeof s,'string');const m=/^(\d{4}-(?:0[1-9]|1[0-2])-(?:0[1-9]|[12]\d|3[01])T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d)\.([0-9]{1,7})Z$/.exec(s);assert.ok(m,'Exact UTC birth timestamp with one through seven fractional digits');return m[1]+'.'+m[2].padEnd(7,'0')+'Z';}
