 for(const k of['allOriginalIdentitiesAbsent','rootDescendantsAbsent','profileMatchesAbsent','privatePortsEmpty','user8080Unchanged','profilePreserved'])assert.equal(p[k],true);for(const k of['newProcessActions','newBrowserRuns','newNativeInputs'])assert.equal(p[k],0);assert.equal(p.originalFlagsRewritten,false);assert.equal(p.samples.length,2);v53VerifyBytes(files,p.sampler.path,p.sampler,128*1024);assert.equal(p.sampler.path,'build/impact-skill-20261014/sample-v53-post-exit-v1.ps1');
 const identity=q=>({ProcessId:q.ProcessId,ParentProcessId:q.ParentProcessId,CreationDate:v53ExactBirthTime(q.CreationDate),ExecutablePath:q.ExecutablePath}),key=q=>q.ProcessId+'|'+q.CreationDate+'|'+q.ExecutablePath,expected=[...union.owned,...cleanup.exitVerification.rootDescendants].map(identity),canonical=xs=>xs.slice().sort((a,b)=>key(a).localeCompare(key(b)));assert.equal(new Set(expected.map(key)).size,expected.length);assert.equal(p.originalTargets,expected.length);let priorAt=Date.parse(result.finishedAt);assert.ok(Number.isFinite(priorAt));
