const v53Next=n=>((n+1)>>>0)||1;
const v53Clone=x=>structuredClone(x);
function v53Item(bytes,id,index){const b=Buffer.from(bytes),at=b.readUInt32LE((id-1)*4),len=b.readUInt32LE(at),count=b.readUInt16LE(at+6),fixed=b.readUInt32LE(at+8);assert.equal(b.readUInt16LE(at+4),id);assert.ok(index<count&&at+len<=b.length);const off=fixed?14+fixed*index:count===1?14:b.readUInt32LE(at+14+index*8),size=fixed||(count===1?len-14:b.readUInt32LE(at+18+index*8));assert.ok(off>=14&&off+size<=len);return b.subarray(at+off,at+off+size);}
